package lk.repairdesk.api.controller; import jakarta.validation.Valid; import lk.repairdesk.api.domain.RepairStatus; import lk.repairdesk.api.dto.RepairDtos.*; import lk.repairdesk.api.service.RepairService; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/repairs") public class RepairController {private final RepairService s;public RepairController(RepairService s){this.s=s;}@PostMapping @PreAuthorize("hasRole('CUSTOMER')") ResponseEntity<Response> create(@Valid @RequestBody CreateRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));}@GetMapping Page<Response> search(@RequestParam(required=false)RepairStatus status,@RequestParam(required=false)String q,@PageableDefault(size=10,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return s.search(status,q,p);}@PatchMapping("/{id}/assign") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") Response assign(@PathVariable Long id,@Valid @RequestBody AssignTechnician r){return s.assign(id,r);}@PatchMapping("/{id}/status") @PreAuthorize("hasAnyRole('TECHNICIAN','MANAGER','ADMIN')") Response status(@PathVariable Long id,@Valid @RequestBody UpdateStatus r){return s.status(id,r);}}